import QtQuick
import Quickshell
import qs.Commons
import qs.Ui

ShellRoot {
  id: shellRoot

  readonly property string pluginDir: "/tmp/opencode/drawercopy"
  readonly property string fp: "/usr/share/omarchy/shell/plugins"
  property var service: null
  property var activePopout: null
  property var drawerSettings: ({ items: ["omarchy.clock", "omarchy.keyboard-layout", "omarchy.audio", "parker.drawer", "omarchy.clock", "test.a", "test.b"] })

  QtObject {
    id: registry
    property var widgets: ({})
    property int revision: 0
    function metadataFor(id) { var e = widgets[String(id)]; return e ? e.metadata : null }
  }

  Component {
    id: testPanelComp
    WidgetButton {
      id: tp
      property bool opened: false
      text: "T"
      function open() { opened = true; if (bar) bar.requestPopout(tp) }
      function close() { opened = false; if (bar) bar.releasePopout(tp) }
    }
  }

  function register(id, comp) {
    var next = {}
    for (var k in registry.widgets) next[k] = registry.widgets[k]
    next[id] = { component: comp, metadata: { allowMultiple: false } }
    registry.widgets = next
  }

  function loadWidget(id, path) {
    var comp = Qt.createComponent("file://" + path, Component.PreferSynchronous)
    if (comp.status !== Component.Ready) { console.log("TEST comp fail", id, comp.errorString()); return }
    register(id, comp)
  }

  QtObject {
    id: scopedShell
    function serviceFor(id) { return id === "parker.drawer" ? shellRoot.service : null }
    function firstPartyServiceFor(id) { return null }
    function updateEntryInline(id, settings) {
      console.log("TEST updateEntryInline", id, JSON.stringify(settings))
      if (id === "parker.drawer") shellRoot.drawerSettings = settings
      return true
    }
  }

  PluginBarApi {
    id: pluginBar
    pluginId: "parker.drawer"
    moduleName: "parker.drawer"
    shell: scopedShell
    foreground: "#cacccc"; barForeground: "#cacccc"; background: "#101010"; urgent: "#ff0000"
    fontFamily: "monospace"
    position: "top"; vertical: false; barSize: 26
    layoutConfig: ({ right: [{ id: "omarchy.audio" }, { id: "parker.drawer" }] })
    _requestPopout: function(owner) { shellRoot.activePopout = owner }
    _releasePopout: function(owner) { if (shellRoot.activePopout === owner) shellRoot.activePopout = null }
    _run: function(c) { console.log("TEST run", c) }
  }

  PanelWindow {
    anchors { top: true; left: true; right: true }
    implicitHeight: 26
    Row {
      anchors.right: parent.right
      Loader {
        id: drawerLoader
        active: false
        source: "file://" + shellRoot.pluginDir + "/Widget.qml"
        onLoaded: {
          item.bar = pluginBar
          item.moduleName = "parker.drawer"
          item.settings = Qt.binding(function() { return shellRoot.drawerSettings })
        }
      }
    }
  }

  function slots(w) {
    return w.hostedSlots.map(function(s) { return s.moduleName + (s.activeItem ? "(" + Math.round(s.width) + "x" + Math.round(s.height) + ")" : "(none)") }).join(",")
  }

  Timer {
    property int step: 0
    interval: 400; repeat: true; running: true
    onTriggered: {
      var w = drawerLoader.item
      step++
      try {
        if (step === 1) {
          var sc = Qt.createComponent("file://" + shellRoot.pluginDir + "/Service.qml", Component.PreferSynchronous)
          shellRoot.service = sc.createObject(null)
          shellRoot.service.manifest = { id: "parker.drawer" }
          shellRoot.service.barWidgetRegistry = registry
          shellRoot.loadWidget("omarchy.clock", shellRoot.fp + "/panels/clock/BarWidget.qml")
          shellRoot.loadWidget("omarchy.keyboard-layout", shellRoot.fp + "/bar/widgets/KeyboardLayout.qml")
          shellRoot.register("test.a", testPanelComp)
          shellRoot.register("test.b", testPanelComp)
          drawerLoader.active = true
        } else if (step === 2) {
          console.log("TEST service found:", !!w.service, "slots before open:", w.hostedSlots.length)
          w.open()
        } else if (step === 3) {
          console.log("TEST opened:", w.opened, "bar popout is drawer:", shellRoot.activePopout === w, "slots:", slots(w))
          var a = w.hostedItems("test.a")[0], b = w.hostedItems("test.b")[0]
          a.open(); b.open()
          console.log("TEST one hosted popup at a time:", !a.opened && b.opened)
          var win = a.QsWindow.window
          var card = a.parent; while (card && !("borderSpec" in card)) card = card.parent
          console.log("TEST drawer window h:", win.height, "card:", card.x, card.y, card.width, card.height)
          w.hostedItems("omarchy.clock")[0].cycleFormat()
          w.close()
          console.log("TEST close: drawer", w.opened, "hosted popup closed:", !b.opened, "bar popout cleared:", shellRoot.activePopout === null)
        } else if (step === 4) {
          console.log("TEST still mounted after close:", w.hostedSlots.length)
          shellRoot.service.ipc.togglePanel("test.b")
        } else if (step === 5) {
          console.log("TEST ipc togglePanel: drawer", w.opened, "b", w.hostedItems("test.b")[0].opened)
          shellRoot.service.ipc.toggle()
          console.log("TEST ipc toggle closes:", !w.opened)
          drawerLoader.active = false
        } else if (step === 6) {
          console.log("TEST hosts after unload:", shellRoot.service.hosts.length)
          console.log("TEST DONE")
          Qt.quit()
        }
      } catch (e) {
        console.log("TEST EXCEPTION at step", step, e, e.stack)
      }
    }
  }
}

