          w.open()
        } else if (step === 3) {
          console.log("TEST opened:", w.opened, "bar popout is drawer:", shellRoot.activePopout === w, "slots:", slots(w))
          var a = w.hostedItems("test.a")[0], b = w.hostedItems("test.b")[0]
