        } else if (step === 4) {
          console.log("TEST still mounted after close:", w.hostedSlots.length)
          shellRoot.service.ipc.togglePanel("test.b")
        } else if (step === 5) {
          console.log("TEST ipc togglePanel: drawer", w.opened, "b", w.hostedItems("test.b")[0].opened)
          shellRoot.service.ipc.toggle()
          console.log("TEST ipc toggle closes:", !w.opened)
          drawerLoader.active = false
        } else if (step === 6) {
          console.log("TEST hosts after unload:", shellRoot.service.hosts.length)
          console.log("TEST DONE")
          Qt.quit()
        }
      } catch (e) {
        console.log("TEST EXCEPTION at step", step, e, e.stack)
      }
    }
  }
